"""Notify me node generated by aotn_node_helper."""

from typing import Any, ClassVar, Dict, List, Optional

from ... import hermes_folder as hermes
from ...node_base import Node, NodeContext
from ...node_category import NodeCategory
from ...node_errors import NodeError


class HermesNotifyNode(Node):
    """Queues a message that Hermes sends you on Telegram."""

    node_type: ClassVar[str] = 'hermes_notify_node'
    display_name: ClassVar[str] = 'Notify me'
    default_alias: ClassVar[str] = 'Notify me'
    description: ClassVar[str] = 'Queues a message that Hermes sends you on Telegram'
    category: ClassVar[str] = NodeCategory.IO
    primary_family: ClassVar[str] = 'Outputs'
    tags: ClassVar[List[str]] = ['Hermes', 'Telegram', 'message']
    icon_name: ClassVar[str] = 'send'
    color_hint: ClassVar[str] = 'amber'
    group: ClassVar[Optional[str]] = 'Hermes'
    selector_section: ClassVar[Optional[str]] = None
    input_ports: ClassVar[List[str]] = ['input']
    output_ports: ClassVar[List[str]] = ['default']
    input_port_metadata: ClassVar[Dict[str, Dict[str, Any]]] = {'input': {'name': 'Input', 'description': 'The value {input} puts in the message', 'data_type': 'any', 'required': False, 'sources': ['upstream', 'vault']}}
    output_port_metadata: ClassVar[Dict[str, Dict[str, Any]]] = {'default': {'name': 'Receipt', 'description': 'Receipt id, status (queued, skipped or not queued) and the message as queued', 'data_type': 'var', 'required': False, 'to': ['downstream', 'vault'], 'pass_through': True}}
    default_config: ClassVar[Dict[str, Any]] = {'input_source': 'Upstream payload', 'input_vault_key': '', 'message': '', 'send_to': 'home', 'priority': 'Normal', 'max_length': 1000, 'skip_repeats_minutes': 0, 'repeat_key': '', 'allow_hermes_commands': False, 'if_not_queued': 'Stop with an error', 'transient_output': False, 'dead_drop_passthrough': True, 'transient_outputs': [], 'vault_write': False, 'vault_write_key': '', 'vault_write_description': ''}
    config_schema: ClassVar[Dict[str, Dict[str, Any]]] = {'input_source': {'type': 'select', 'label': 'Input source', 'options': ['Upstream payload', 'Vault'], 'tab': 'Source', 'section': 'Optional Inputs', 'description': 'The value {input} puts in the message'}, 'input_vault_key': {'type': 'string', 'label': 'Input Vault key', 'required': False, 'tab': 'Source', 'section': 'Optional Inputs', 'vault_type': 'any', 'visible_when': {'input_source': 'Vault'}}, 'message': {'type': 'multiline', 'label': 'Message', 'placeholder': '{input} = the incoming value. Blank sends just that', 'tab': 'Parameters'}, 'send_to': {'type': 'select', 'label': 'Send to', 'options': [['home · set up in Hermes', 'home']], 'options_from_setting': 'hermes_send_to_names', 'option_summary': 'set up in Hermes', 'tab': 'Parameters'}, 'priority': {'type': 'select', 'label': 'Priority', 'options': [['Normal · in the next message', 'Normal'], ['Urgent · first, marked ⚠', 'Urgent']], 'tab': 'Parameters'}, 'max_length': {'type': 'integer', 'label': 'Longest message (characters)', 'minimum': 1, 'maximum': 3500, 'placeholder': '1000, up to 3500', 'tab': 'Parameters'}, 'skip_repeats_minutes': {'type': 'number', 'label': 'Skip repeats for (minutes)', 'minimum': 0, 'maximum': 1440, 'placeholder': '0 = never skip', 'tab': 'Parameters'}, 'repeat_key': {'type': 'string', 'label': 'Repeat key', 'placeholder': 'same run + node + branch', 'tab': 'Parameters'}, 'allow_hermes_commands': {'type': 'boolean', 'label': 'Allow Hermes commands (\\[SILENT], MEDIA:)', 'tab': 'Parameters'}, 'if_not_queued': {'type': 'select', 'label': "If it can't be queued", 'options': [['Stop · the node fails', 'Stop with an error'], ['Carry on · the run continues', 'Carry on']], 'tab': 'Parameters'}}
    ui_hints: ClassVar[Dict[str, Any]] = {'forwarded_input_port': 'input'}
    error_definitions: ClassVar[List[Dict[str, Any]]] = [{'code': 'outbox_unwritable', 'description': 'The Hermes folder could not be written.', 'retryable': True}, {'code': 'unknown_destination', 'description': 'Send to is not one of the names in Options (hermes_send_to_names).', 'retryable': False}]

    async def execute(self, context: NodeContext) -> None:
        text = hermes.as_text(hermes.node_input(self, context))
        template = str(self.config.get("message") or "")
        message = template.replace("{input}", text) if template.strip() else text
        if not self.config.get("allow_hermes_commands"):
            message = hermes.escape(message)
        message = hermes.cut(message, self._longest())

        send_to = str(self.config.get("send_to") or "").strip()
        if send_to not in hermes.send_to_names(context.get_setting) or not hermes.NAME_PATTERN.match(send_to):
            context.signal_error(NodeError(
                "unknown_destination",
                f"Send to {send_to!r} is not one of the names in Options (hermes_send_to_names)",
                details={"send_to": send_to},
            ))
            return
        if not message.strip():
            hermes.finish(self, context, {"receipt_id": "", "status": "nothing to send", "message": ""}, "var")
            return

        origin = hermes.origin_of(context)
        try:
            receipt = hermes.queue_message(
                context.get_setting,
                origin=origin,
                send_to=send_to,
                priority="urgent" if self.config.get("priority") == "Urgent" else "normal",
                message=message,
                hermes_commands=bool(self.config.get("allow_hermes_commands")),
                repeat_key=str(self.config.get("repeat_key") or "").strip() or hermes.default_repeat_key(origin),
                repeat_minutes=hermes.repeat_minutes(self.config.get("skip_repeats_minutes")),
            )
        except OSError as exc:
            if self.config.get("if_not_queued") == "Carry on":
                receipt = {"receipt_id": "", "status": "not queued", "message": message}
            else:
                context.signal_error(NodeError(
                    "outbox_unwritable", f"Could not write the Hermes folder: {exc}",
                    details={"folder": str(hermes.folder(context.get_setting))}, retryable=True,
                ))
                return
        hermes.finish(self, context, receipt, "var")

    def _longest(self) -> int:
        try:
            length = int(self.config.get("max_length"))
        except (TypeError, ValueError):
            return hermes.DEFAULT_MESSAGE_LENGTH
        return min(max(length, 1), hermes.MESSAGE_LIMIT)
